"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[57806],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},84024:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>u,contentTitle:()=>d,default:()=>l,frontMatter:()=>a,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"2023/03/31","title":"2023-03-31","description":"US-Verbotsgesetz wirft Bedenken f\xfcr VPNs & TikTok auf","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/03/31.md","sourceDirName":"2023/03","slug":"/2023/03/31","permalink":"/de/2023/03/31","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/03/31.md","tags":[],"version":"current","frontMatter":{"localized_date":"31. M\xe4rz 2023","top_news":"US-Verbotsgesetz wirft Bedenken f\xfcr VPNs & TikTok auf"},"sidebar":"defaultSidebar","previous":{"title":"01","permalink":"/de/2023/04/01"},"next":{"title":"2023-03-30","permalink":"/de/2023/03/30"}}');var t=i(23420),s=i(3331);const a={localized_date:"31. M\xe4rz 2023",top_news:"US-Verbotsgesetz wirft Bedenken f\xfcr VPNs & TikTok auf"},d="2023-03-31",u={},h=[{value:"US-Verbotsgesetz wirft Bedenken f\xfcr VPNs &amp; TikTok auf",id:"us-verbotsgesetz-wirft-bedenken-f\xfcr-vpns--tiktok-auf",level:2},{value:"Gemischte Ansichten \xfcber den Wert von Y Combinator f\xfcr Startups",id:"gemischte-ansichten-\xfcber-den-wert-von-y-combinator-f\xfcr-startups",level:2},{value:"Scratch: Beliebte visuelle Programmiersprache f\xfcr Kinder",id:"scratch-beliebte-visuelle-programmiersprache-f\xfcr-kinder",level:2},{value:"Herausforderungen und Kompromisse in der LED-Beleuchtungstechnologie",id:"herausforderungen-und-kompromisse-in-der-led-beleuchtungstechnologie",level:2},{value:"\xdcber die H\xe4lfte der neuen NPM-Pakete sind Spam",id:"\xfcber-die-h\xe4lfte-der-neuen-npm-pakete-sind-spam",level:2},{value:"US-Gesetzesentw\xfcrfe mit Bedrohungen f\xfcr die technische Freiheit und den Datenschutz",id:"us-gesetzesentw\xfcrfe-mit-bedrohungen-f\xfcr-die-technische-freiheit-und-den-datenschutz",level:2},{value:"Open-Source 3D Rendering Engine f\xfcr Bildung und Integration",id:"open-source-3d-rendering-engine-f\xfcr-bildung-und-integration",level:2},{value:"Google bestreitet die Verwendung von OpenAIs ChatGPT zum Trainieren von Bard",id:"google-bestreitet-die-verwendung-von-openais-chatgpt-zum-trainieren-von-bard",level:2},{value:"Twitter API vernachl\xe4ssigt, Unzufriedenheit der Nutzer w\xe4chst",id:"twitter-api-vernachl\xe4ssigt-unzufriedenheit-der-nutzer-w\xe4chst",level:2},{value:"Der Direktor der Polizeigewerkschaft von San Jose wird des Drogenschmuggels beschuldigt",id:"der-direktor-der-polizeigewerkschaft-von-san-jose-wird-des-drogenschmuggels-beschuldigt",level:2}];function o(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-03-31",children:"2023-03-31"})}),"\n",(0,t.jsx)(n.h2,{id:"us-verbotsgesetz-wirft-bedenken-f\xfcr-vpns--tiktok-auf",children:"US-Verbotsgesetz wirft Bedenken f\xfcr VPNs & TikTok auf"}),"\n",(0,t.jsxs)(n.p,{children:["Ein vom Wei\xdfen Haus unterst\xfctztes US-Verbotsgesetz zur Regulierung des Internets k\xf6nnte VPNs illegal machen, Geldstrafen von bis zu 1 Million Dollar und 20 Jahre Haft nach sich ziehen und als Angriff auf die b\xfcrgerlichen Freiheiten betrachtet werden. Der Gesetzentwurf wird von beiden Parteien unterst\xfctzt und konzentriert sich auf nationale Sicherheitsbedenken in Bezug auf China und die Einschr\xe4nkung von Gesch\xe4ftsbeziehungen mit diesem Land. Die EU wird dem US-Trend m\xf6glicherweise nicht folgen, da die L\xe4nder ihre eigene Rechtsstruktur haben, und das Verbot von TikTok k\xf6nnte zu Unmut unter jungen Menschen und zu Vergeltungsma\xdfnahmen gegen die US-Regierung f\xfchren. Die Kritiker des Verbots argumentieren, dass es die Privatsph\xe4re des Einzelnen sowie die Rede- und Meinungsfreiheit bedroht.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35366955",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://www.youtube.com/watch?v=FWQGA_n5Z4M",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"gemischte-ansichten-\xfcber-den-wert-von-y-combinator-f\xfcr-startups",children:"Gemischte Ansichten \xfcber den Wert von Y Combinator f\xfcr Startups"}),"\n",(0,t.jsxs)(n.p,{children:["Die Meinungen \xfcber den Wert von Y Combinator (YC) f\xfcr Startups sind gemischt und h\xe4ngen von den individuellen Perspektiven und Bed\xfcrfnissen ab. W\xe4hrend die einen das Netzwerk und die Mentorenschaft von YC sch\xe4tzen, kritisieren andere die Beratung und den Fokus auf kurzfristige Ziele. Der Ruf und die Marke von YC k\xf6nnen bei der Mittelbeschaffung hilfreich sein, aber der nicht gedeckelte SAFE-Deal und die Betonung der Skalierung um jeden Preis sind m\xf6glicherweise nicht f\xfcr alle Gr\xfcnder geeignet. Auch die Bedeutung des Aufbaus einer Gemeinschaft und pers\xf6nlicher Beziehungen in einem reinen Remote-Format ist umstritten. Letztendlich h\xe4ngt der Wert von YC von der F\xe4higkeit eines Gr\xfcnders ab, die Ressourcen zu nutzen, um die Erfolgschancen zu maximieren.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35373019",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://acecreamu.substack.com/p/is-y-combinator-worth-the-money",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"scratch-beliebte-visuelle-programmiersprache-f\xfcr-kinder",children:"Scratch: Beliebte visuelle Programmiersprache f\xfcr Kinder"}),"\n",(0,t.jsxs)(n.p,{children:["Scratch ist eine beliebte visuelle Programmiersprache f\xfcr Kinder, die bunte Bl\xf6cke anstelle von textbasierter Kodierung verwendet, um ihnen das Erlernen von Programmierkonzepten zu erleichtern. Das Programm umfasst grundlegende Programmierprinzipien wie Variablen, Listen, if/else- und Schleifen-Kontrollflussstrukturen und ereignisbasierte Gleichzeitigkeit. Scratch hat einen einfachen, benutzerfreundlichen Ansatz, um Kinder zu ermutigen, Berechnungen auf kreative Art und Weise zu erforschen, und legt einen gro\xdfen Schwerpunkt auf die Interaktion mit Gleichaltrigen und das Teilen von Arbeiten, um Feedback zu erhalten. Die Scratch-Gemeinschaft ist eine der gr\xf6\xdften Programmiergemeinschaften der Welt mit \xfcber 103 Millionen Nutzern und 123 Millionen gemeinsamen Projekten auf der Plattform. Es gibt zwar Bedenken hinsichtlich unregulierter sozialer Netzwerke und Kinder, die Videospiele spielen, anstatt Scratch f\xfcr Bildungszwecke zu nutzen, aber das Tool hat viele dazu inspiriert, sich f\xfcr das Programmieren zu interessieren, wobei die Projekte von Anf\xe4ngern bis zu fortgeschrittenen Programmierern reichen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35373052",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://scratch.mit.edu/about",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"herausforderungen-und-kompromisse-in-der-led-beleuchtungstechnologie",children:"Herausforderungen und Kompromisse in der LED-Beleuchtungstechnologie"}),"\n",(0,t.jsxs)(n.p,{children:["LED-Gl\xfchbirnen haben Probleme mit schnellem Ausfall, schlechter Farbwiedergabe und spektralen \xc4hnlichkeitsindizes, schlecht konzipierten Netzteilen, \xdcberhitzung und h\xf6heren Kosten f\xfcr die Innenbeleuchtung. F\xfcr LED-Beleuchtung sind Konstantstrom-Netzteile erforderlich, und die Leuchten m\xfcssen anders konstruiert werden als Gl\xfchlampen, um die W\xe4rme abzuleiten. Es gibt Bedenken hinsichtlich der Zuverl\xe4ssigkeit und Langlebigkeit von LED-Lampen, obwohl qualitativ hochwertige Optionen zu einem h\xf6heren Preis erh\xe4ltlich sind. Die Integration von LED-Lampen mit Dimmern und die Gew\xe4hrleistung der Kompatibilit\xe4t stellen eine Herausforderung dar. Das Flackern und die mangelnde Lebendigkeit der LED-Beleuchtung haben zur Entwicklung neuer Klassifizierungssysteme und abstimmbarer LED-Lampen gef\xfchrt. Insgesamt hat die LED-Technologie Potenzial, erfordert aber eine kontinuierliche Entwicklung und Innovation.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35371750",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://nymag.com/strategist/article/led-light-bulbs-investigation.html",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"\xfcber-die-h\xe4lfte-der-neuen-npm-pakete-sind-spam",children:"\xdcber die H\xe4lfte der neuen NPM-Pakete sind Spam"}),"\n",(0,t.jsxs)(n.p,{children:["Mehr als die H\xe4lfte der neu eingereichten npm-Pakete sind Spam. Viele davon enthalten Links zu b\xf6sartigen Websites oder bieten gef\xe4lschte Werbegeschenke wie Fortnite V-Bucks an. Es wird vermutet, dass die Zunahme von Spam mit Coding Boot Camps zusammenh\xe4ngt, in denen Studenten ermutigt werden, Pakete zu ver\xf6ffentlichen, auch wenn sie nichts bewirken. Die Befragten haben L\xf6sungen wie automatisierte Testverfahren und ein Web-of-Trust-Modell vorgeschlagen. Das Thema wirft ein Schlaglicht auf die komplexe Natur der Ethik in der Softwareentwicklungsbranche und die Spannungen zwischen freier Meinungs\xe4u\xdferung und privaten Eigentumsrechten. Sicherheitsforscher haben das Vorhandensein von Spam-Paketen in der gesamten npm-Registrierung festgestellt und f\xfchren weitere Untersuchungen durch.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35370728",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://blog.sandworm.dev/one-in-two-new-npm-packages-is-seo-spam-right-now",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"us-gesetzesentw\xfcrfe-mit-bedrohungen-f\xfcr-die-technische-freiheit-und-den-datenschutz",children:"US-Gesetzesentw\xfcrfe mit Bedrohungen f\xfcr die technische Freiheit und den Datenschutz"}),"\n",(0,t.jsxs)(n.p,{children:['Die US-Regierung hat einen Gesetzentwurf vorgelegt, der ihr die beispiellose Befugnis einr\xe4umt, jede ausl\xe4ndische Technologie zu verbieten, die sie als "Bedrohung der nationalen Sicherheit" ansieht, was einige zu der Bef\xfcrchtung veranlasst, dass dies zu Zensurbefugnissen \xe4hnlich denen Chinas f\xfchren und viel weiter reichen k\xf6nnte als urspr\xfcnglich angenommen. Es gibt auch eine Debatte \xfcber das Verbot von in chinesischem Besitz befindlichen Social-Media-Apps, wobei einige argumentieren, dass dies ein Ausrutscher in Richtung Zensur von Informationen sei, w\xe4hrend andere argumentieren, dass dies notwendig sei, um chinesische Unternehmen daran zu hindern, US-Technologie zu stehlen und Informationen zu Spionagezwecken zu sammeln. Der RESTRICT Act ist ein Gesetzesvorschlag, mit dem TikTok und VPNs verboten werden k\xf6nnten, und Kritiker argumentieren, dass dies gegen den ersten Verfassungszusatz versto\xdfen k\xf6nnte. Republikanische Senatoren haben auch vorgeschlagen, Bundesbediensteten die Nutzung von Social-Media-Apps chinesischer Unternehmen zu verbieten, weil sie Spionage und \xdcberwachung bef\xfcrchten. Einige Kommentatoren meinen, dass die Gesetzgebung auf Protektionismus seitens der Regierung hinausl\xe4uft, w\xe4hrend andere argumentieren, dass das Wachstum der sozialen Medien der geistigen Gesundheit schadet und zur Manipulation der \xf6ffentlichen Meinung beitr\xe4gt.\n',(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35369075",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://www.vice.com/en/article/4a3ddb/restrict-act-insanely-broad-ban-tiktok-vpns",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"open-source-3d-rendering-engine-f\xfcr-bildung-und-integration",children:"Open-Source 3D Rendering Engine f\xfcr Bildung und Integration"}),"\n",(0,t.jsxs)(n.p,{children:["Eine Open-Source 3D-Rendering-Engine von StratusGFX wurde von einem Entwickler ver\xf6ffentlicht, um den Rendering-Code in andere Engines zu integrieren oder als Bildungsressource zu nutzen. Zu ihren F\xe4higkeiten geh\xf6ren Echtzeit-Reflexionen, Schatten und vollst\xe4ndige PBR-Schattierungsunterst\xfctzung, aber sie unterst\xfctzt derzeit nur OpenGL. Sein Sch\xf6pfer erw\xe4gt, den Renderer auf Vulkan zu portieren, um die plattform\xfcbergreifende Kompatibilit\xe4t zu verbessern. Die StratusGFX-Engine wurde entwickelt, um den Realismus zu maximieren, aber mit Kompromissf\xe4higkeiten f\xfcr weniger leistungsstarke Hardware, und ihre Architektur ist auf Github f\xfcr Windows und Linux verf\xfcgbar. Die Engine befindet sich in der Pre-Release/Beta-Release-Phase, und es ist mit erheblichen Fehlern und Instabilit\xe4t zu rechnen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35370284",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://github.com/KTStephano/StratusGFX",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"google-bestreitet-die-verwendung-von-openais-chatgpt-zum-trainieren-von-bard",children:"Google bestreitet die Verwendung von OpenAIs ChatGPT zum Trainieren von Bard"}),"\n",(0,t.jsxs)(n.p,{children:["Google dementiert die Verwendung von OpenAIs ChatGPT, um Bard, ein neues Sprachmodell, zu trainieren. Es wurden Bedenken ge\xe4u\xdfert, ob es ethisch vertretbar ist, ein gro\xdfes Sprachmodell mit dem Output eines anderen, kommerziell kontrollierten LLM zu trainieren. Die Nutzungsbedingungen von OpenAI verbieten es, Modelle von Wettbewerbern mit den Ergebnissen des ML zu trainieren, aber Google ist nicht daran gebunden. Ein ehemaliger Google-Mitarbeiter behauptete, OpenAI-Daten verwendet zu haben, aber Google bestreitet dies. KI-generiertes Material ist nicht urheberrechtsf\xe4hig, und das Training mit anderen Modellausgaben ist zul\xe4ssig. Einige argumentieren, dass das Stehlen von ChatGPT moralisch gerechtfertigt sein k\xf6nnte, da es von einer Gruppe stammt, aber das Trainieren von Modellen auf anderen KI-generierten Daten k\xf6nnte schlechte Daten erzwingen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35370915",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://twitter.com/steventey/status/1641267979399704576",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"twitter-api-vernachl\xe4ssigt-unzufriedenheit-der-nutzer-w\xe4chst",children:"Twitter API vernachl\xe4ssigt, Unzufriedenheit der Nutzer w\xe4chst"}),"\n",(0,t.jsxs)(n.p,{children:["Die Twitter-API wird Berichten zufolge nicht gewartet, was zu Instabilit\xe4tsproblemen f\xfcr die Nutzer f\xfchrt. Einige Nutzer haben berichtet, dass sie sich von dem Dienst entfremdet f\xfchlen, weil der Anteil wissenschaftlicher Arbeiten abnimmt und der Anteil hetzerischer oder beleidigender Inhalte zunimmt. Viele Social-Media-Plattformen verwenden algorithmische Feeds, aber die Standardeinstellungen sind wichtig, da sie das Nutzerverhalten beeinflussen. Twitter-Nutzer haben mit Problemen wie internen Serverfehlern und Schwierigkeiten beim Zugriff auf die Website zu k\xe4mpfen, was einige dazu veranlasst, auf alternative Plattformen wie Mastodon auszuweichen. Die j\xfcngsten Instabilit\xe4tsprobleme von Twitter haben einige Nutzer dazu veranlasst, ihre Nutzung einzuschr\xe4nken. Trotz dieser Bedenken sind einige der Meinung, dass das Wachstum von Twitter unter der F\xfchrung von Musk darauf hindeutet, dass die Plattform weiterhin florieren wird, mit oder ohne ihre treuen Nutzer. Die Entscheidung von Elon Musk, den Zugang zu Twitters API zu beschr\xe4nken, sorgt f\xfcr Kontroversen. Kritiker werfen ihm vor, Twitter absichtlich in den Ruin zu treiben. Twitters API wird jetzt praktisch nicht mehr gewartet, da nur noch ein Mitarbeiter regelm\xe4\xdfig im Twitter Developers Forum postet und sich ausschlie\xdflich auf die Ads API konzentriert.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35370152",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://snarfed.org/the-twitter-api-is-now-effectively-unmaintained",children:"Original Post"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"der-direktor-der-polizeigewerkschaft-von-san-jose-wird-des-drogenschmuggels-beschuldigt",children:"Der Direktor der Polizeigewerkschaft von San Jose wird des Drogenschmuggels beschuldigt"}),"\n",(0,t.jsxs)(n.p,{children:["Die Gesch\xe4ftsf\xfchrerin der San Jose Police Officers Association, Sonia Rosa Segovia, wurde angeklagt, Fentanyl in die USA geschmuggelt und ein Drogengesch\xe4ft teilweise von ihrem B\xfcro aus betrieben zu haben. Segovia soll die Adresse der Vereinigung genutzt haben, um Pakete an Kunden zu versenden, und mit ihren Lieferanten \xfcber Polizeigesch\xe4fte gesprochen haben. Mindestens einer ihrer Kunden starb an einer \xdcberdosis, und sie ist wegen mehrerer Drogenvergehen angeklagt. Andere F\xe4lle von Polizeibeamten, die in den Drogenhandel verwickelt waren, haben Fragen \xfcber die Rolle der Strafverfolgungsbeh\xf6rden im illegalen Drogenhandel aufgeworfen, wobei einige die Legalisierung als L\xf6sung vorschlagen. Die Diskussion \xfcber die Legalisierung von Drogen ber\xfchrt auch die externen Effekte und den Bedarf an Unterst\xfctzungssystemen. Die Gesch\xe4ftsf\xfchrerin der Polizeigewerkschaft von San Jose, Joanne Southerland, wurde ebenfalls wegen Drogenschmuggels angeklagt, ebenso wie Joanne Segovia, eine Angestellte der Polizeigewerkschaft, die wegen der Einfuhr von Methamphetamin in die USA angeklagt wurde. Diese F\xe4lle machen deutlich, dass L\xf6sungen f\xfcr die Bek\xe4mpfung des Drogenhandels und der Drogensucht gefunden werden m\xfcssen, einschlie\xdflich kultureller Ver\xe4nderungen und gezielter Strafverfolgungsma\xdfnahmen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35376488",children:"Hacker News Link"}),", ",(0,t.jsx)(n.a,{href:"https://www.washingtonexaminer.com/news/crime/san-jose-police-union-director-smuggle-fentanyl-charge",children:"Original Post"}),"."]})]})}function l(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(o,{...e})}):o(e)}}}]);